<template><Teleport to="body"><div v-if="open" class="vs-modal-layer" @mousedown.self="dismiss"><section ref="panel" class="vs-modal" role="dialog" aria-modal="true" :aria-labelledby="titleId" :aria-describedby="description ? descriptionId : undefined" @keydown="handleKeydown"><header><div><h2 :id="titleId">{{title}}</h2><p v-if="description" :id="descriptionId">{{description}}</p></div><BaseButton variant="ghost" icon-only aria-label="Đóng hộp thoại" @click="dismiss"><template #icon>×</template></BaseButton></header><div class="vs-modal__content"><slot /></div><footer v-if="$slots.footer"><slot name="footer" /></footer></section></div></Teleport></template>
<script setup>
import { nextTick, onBeforeUnmount, ref, watch } from 'vue'; import BaseButton from './BaseButton.vue';
const props=defineProps({open:Boolean,title:{type:String,required:true},description:{type:String,default:''},closeOnEscape:{type:Boolean,default:true}});const emit=defineEmits(['close']);const panel=ref(null);const titleId=`modal-title-${Math.random().toString(36).slice(2)}`;const descriptionId=`${titleId}-description`;let previousFocus=null;
function focusable(){return [...(panel.value?.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')||[])]}function dismiss(){emit('close')}function handleKeydown(e){if(e.key==='Escape'&&props.closeOnEscape){e.preventDefault();dismiss()}if(e.key==='Tab'){const items=focusable();if(!items.length){e.preventDefault();return}const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}
watch(()=>props.open,async(value)=>{if(value){previousFocus=document.activeElement;document.body.style.overflow='hidden';await nextTick();(focusable()[0]||panel.value)?.focus()}else{document.body.style.overflow='';previousFocus?.focus?.()}},{immediate:true});onBeforeUnmount(()=>{document.body.style.overflow=''})
</script>
<style scoped>.vs-modal-layer{position:fixed;inset:0;z-index:1000;display:grid;place-items:center;padding:var(--space-4);background:var(--surface-overlay)}.vs-modal{width:min(600px,100%);max-height:min(90vh,760px);display:flex;flex-direction:column;border:1px solid var(--border-default);border-radius:var(--radius-modal);background:var(--surface-raised);color:var(--text-primary);box-shadow:var(--shadow-overlay);overflow:hidden}.vs-modal>header,.vs-modal>footer{display:flex;align-items:flex-start;justify-content:space-between;gap:var(--space-4);padding:var(--space-5);border-bottom:1px solid var(--border-subtle)}.vs-modal>footer{justify-content:flex-end;border-top:1px solid var(--border-subtle);border-bottom:0}.vs-modal h2{font-size:var(--type-h2-size);line-height:var(--type-h2-line)}.vs-modal header p{color:var(--text-secondary);font-size:var(--type-body-size)}.vs-modal__content{padding:var(--space-5);overflow:auto}@media(max-width:640px){.vs-modal-layer{align-items:end;padding:0}.vs-modal{max-height:92vh;border-radius:var(--radius-modal) var(--radius-modal) 0 0}}</style>
